-season + manta-season preferred vessels ~3-9 months; shoulder nearer term; confirm per-vessel","off_season_specials":"monsoon-turn shoulder weeks lower demand","event_peaks":"Jun-Oct SW-monsoon manta/whale-shark (Hanifaru)","fire_date":"manta-season fire Mar-Apr; clear-water NE-season fire Aug-Sep"},"jewels":[{"name":"Hanifaru Bay (Baa Atoll)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Jun-Oct manta/whale-shark aggregation, snorkel-only core","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Jun-Oct manta/whale-shark aggregation, snorkel-only core","when":"Dec-Apr","commission":"fleet-direct (Aggressor/Explorer)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","liveaboard","tropical"],"shelf_fit":{"diveglobal":"evidenced","liveaboard":"primary","ocean":"destination","tropical":"evidenced"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Maaya Thila (Ari)","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"classic pinnacle, night diving","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/maldives","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"classic pinnacle, night diving","when":"Dec-Apr","commission":"fleet-direct","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","liveaboard"],"shelf_fit":{"diveglobal":"evidenced","liveaboard":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Donkalo Thila","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"manta cleaning-station thila","bookable_category":"liveaboa