ate Angkor day - dawn temples + scholar guide","why_ultra":"Angkor Wat before the gates, a private Khmer-art historian, chauffeured, Tonle Sap sunset","earning":"DMC + venue","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury-ultra","price_band":"on application"}],"source_verified":"2026-07-29","hero":{"query":"The Mekong, Cambodia, Cambodia"},"geo":{"lat":13.3671,"lng":103.8448},"orbit":[{"id":"mekong-delta-vietnam","jewels":11,"si":["river","culture","deepdive","culinary","adventure","romance","senior"]},{"id":"upper-mekong-laos","jewels":11,"si":["river","culture","deepdive","culinary","adventure","romance","senior"]}],"orbit_country":[]}'::jsonb, 6),
