e_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"granite boulders and swim-throughs, north Similans","when":"Nov-Apr","commission":"fleet-direct","wells":["stay"],"wells_basis":"pass 2 — bookable_category","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"West of Six","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"Similan boulder site with soft corals","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Similan boulder site with soft corals","when":"Nov-Apr","commission":"fleet-direct","wells":["stay"],"wells_basis":"pass 2 — bookable_category","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Boulder City","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"granite ridge and slopes","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"granite ridge and slopes","when":"Nov-Apr","commission":"fleet-direct","wells":["stay"],"wells_basis":"pass 2 — bookable_category","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"East of Eden","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"the reef at Similan Island #7","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"the reef at Similan Island #7","when":"Nov-Apr","commission":"fleet-direct","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Boon Sung Wreck (Khao Lak)","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"muck-and-macro wreck finale near the departure coast","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"muck-and-macro wreck finale near the departure coast","when":"Nov-Apr","commission":"fleet-direct","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["diveglobal","liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"evidenced","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Surin Islands","si_tag":"liveaboard","status":"live","tier":"premier","hook":"northern national park near Richelieu; reef and Moken sea-gypsy villages ashore","bookable_category":"liveaboard berth","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"northern national park near Richelieu; reef and Moken sea-gypsy villages ashore","when":"Nov-Apr","commission":"fleet-direct","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Similan granite core route (Oct-May)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Elephant Head + Christmas Point + Boulder City on the park-season week","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Elephant Head + Christmas Point + Boulder City on the park-season week","when":"Nov-Apr","commission":"fleet-direct (Aggressor)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"North Andaman pelagic route (Feb-Apr)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"Richelieu + Koh Bon + Koh Tachai on the whale-shark/manta weeks","bookable_category":"liveaboard week","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"Richelieu + Koh Bon + Koh Tachai on the whale-shark/manta weeks","when":"Nov-Apr","commission":"fleet-direct (Aggressor)","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["fleet-direct"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Surin Moken villages + Similan national park","si_tag":"globaladv","status":"future","tier":"comfort","hook":"the sea-gypsy villages and the island parks ashore","bookable_category":"liveaboard-included park day / DMC","source":"https://www.liveaboard.com/diving/thailand","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"the sea-gypsy villages and the island parks ashore","when":"Nov-Apr","commission":"DMC (park fee pass-through)","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","liveaboard"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","liveaboard":"evidenced","ocean":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the current advisory for the Similan Islands, and how do I dive them responsibly?","a":"The UK FCDO advises against all but essential travel to those southern provinces, parts of Songkhla and within 20 km of the Cambodia border, and names none of Phuket, Khao Lak, Phang Nga or the Similans. The Similan/Surin coast sits outside every carve-out from both; Carry DAN membership plus separate dive-accident insurance and observe an 18-24 hour no-fly window after diving.","source":"advisory level reported by nationthailand.com + tvc.co.gov 403''d, not read directly); FCDO gov.uk/foreign-travel-advice/thailand/regional-risks read via WebFetch 2026-08-09","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"The Similan liveaboard area is comparatively well covered. The SSS Evacuation Center in Khao Lak, on the Tap Lamu departure coast, runs a 24-hour diving-emergency line and serves the Similan fleet directly; behind it, the SSS Recompression Chamber in Phuket - southern Thailand''s first diver chamber (established 1996), a multiplace chamber taking up to four occupants - operates 24/7 and covers the whole west coast from the Myanmar border to Malaysia. Confirm current contacts and readiness through the operator or DAN before your trip.","source":"ssschambernetwork.com/phuket-thailand + sssnetwork.com/pages/khaohome.html (accessed 2026-08-09)","si_tag":"safety"},{"q":"When can I dive the Similans, and when are whale sharks and mantas most likely?","a":"The season is fixed by the national parks: liveaboards run October-May, and the Similan and Surin parks close in the southwest monsoon (about mid-May to mid-October). Within the season, manta and whale-shark encounters at Richelieu Rock, Koh Bon and Koh Tachai are most associated with the February-April plankton-rich weeks, though sightings are never guaranteed.","source":"liveaboard.com/diving/thailand","si_tag":"planning"},{"q":"Which sites define a Similan liveaboard week?","a":"Richelieu Rock (the marquee), the manta and pelagic pinnacles of Koh Bon and Koh Tachai, and the Similan granite sites - Elephant Head Rock, Christmas Point, West of Six, Boulder City and East of Eden - with the Boon Sung wreck off Khao Lak as a muck-and-macro finale. Longer trips add the Surin Islands.","source":"liveaboard.com/diving/thailand","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"Koh Bon, Koh Tachai and Richelieu Rock are current-swept pinnacles best suited to experienced divers; the Similan boulder sites and the Boon Sung wreck suit a wider range with a guide. Nitrox is standard on liveaboards for the repetitive multi-day profile. Dive within your certification and the operator briefing.","source":"liveaboard.com/diving/thailand","si_tag":"liveaboard"},{"q":"How far ahead do Similan liveaboards book?","a":"Because the season is short and park-gated, the marquee boats and the February-April pelagic weeks fill earliest; hold roughly 4-9 months out for peak windows and preferred vessels, nearer term for the season edges. Confirm per-vessel lead times with the operator.","source":"liveaboard.com/diving/thailand","si_tag":"planning"}],"seo":{"meta_title":"Similan Liveaboard Diving, Thailand: Richelieu & Season","meta_description":"The Similan Islands liveaboard sea - Richelieu Rock, the Koh Bon and Koh Tachai manta pinnacles, granite swim-throughs, the park-gated Oct-May season, operators and safety.","slug":"similan-islands-thailand","primary_keyword":"Similan liveaboard diving","long_tail":["Richelieu Rock whale shark","Koh Bon manta","Similan dive season","Elephant Head Rock","Thailand liveaboard operators"],"search_language":"th (restated, not machine-translated)","local_keywords":["ดำน้ำหมู่เกาะสิมิลัน","ริเชลิว ร็อค","เรือไลฟ์อะบอร์ด"],"hreflang":["en","th"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-09","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-09","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/thailand","read":"2026-08-20T14:53:47Z","source_updated":"2026-06-30T12:30:58+01:00"}]}},"booking":{"codes":[],"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-09","hits":4,"misses":18,"disregarded":3,"note":"Liveaboard-diving scope; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"Private full-boat charter (Thailand Aggressor or premium Thai liveaboard) across the granite core + Richelieu/Koh Bon pelagic weeks + Phuket resort pre/post; optional Myanmar Mergui leg on Master where permits allow","why_ultra":"the Similan ultra pull is a priva